// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 tokenId) public {
        // Ensure we are not the owner to allow acceptOwnership to fail or succeed
        vm.assume(address(this) != c.owner());

        // Try to call acceptOwnership() – it will revert because there is no pending owner
        bool reverted;
        try c.acceptOwnership() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The rule: getRoyalties should revert because the contract was never initialized
        vm.expectRevert();
        c.getRoyalties(tokenId);

        // If we reach here without revert, the bug is present (no initialization check)
        assertTrue(reverted);
    }
}

